shader_type spatial;
render_mode unshaded;

// Assign the same PNG to both samplers in the ShaderMaterial.
uniform sampler2D color_sample : source_color, filter_nearest;
uniform sampler2D raw_sample : filter_nearest;
uniform bool use_color = true;

void fragment() {
	if (use_color) {
		ALBEDO = texture(color_sample, UV).rgb;
	} else {
		ALBEDO = texture(raw_sample, UV).rgb;
	}
}

extends RefCounted
## Curl check for tangent-space normal maps, copied verbatim from the Assignment 5 page (Step 3).
## A real surface's slope field is curl-free; calibrate on a known GL/DX pair before trusting a threshold.

# ~0: slope field of a real surface in this convention.
# ~1: no surface behind it.
# ~2: real surface, other green convention.
static func curl_ratio(source: Image, directx := false, stride := 4) -> float:
    var img := source.duplicate() as Image
    if img.is_compressed():
        img.decompress()
    var s: float = -1.0 if directx else 1.0
    var curl_sq := 0.0
    var terms_sq := 0.0
    for v in range(1, img.get_height() - 1, stride):
        for u in range(1, img.get_width() - 1, stride):
            var t1 := (_dh_du(img, u, v + 1) - _dh_du(img, u, v - 1)) * 0.5
            var t2 := (_dh_dv(img, u + 1, v, s) - _dh_dv(img, u - 1, v, s)) * 0.5
            curl_sq += (t1 - t2) * (t1 - t2)
            terms_sq += t1 * t1 + t2 * t2
    return curl_sq / maxf(terms_sq, 1e-12)

static func _normal(img: Image, u: int, v: int) -> Vector3:
    var c := img.get_pixel(u, v)
    return Vector3(c.r, c.g, c.b) * 2.0 - Vector3.ONE

static func _dh_du(img: Image, u: int, v: int) -> float:
    var n := _normal(img, u, v)
    return -n.x / maxf(n.z, 0.05)

static func _dh_dv(img: Image, u: int, v: int, s: float) -> float:
    var n := _normal(img, u, v)
    return s * n.y / maxf(n.z, 0.05)

extends SceneTree
## Builds the A5 material resources and scenes from CHANGE-BRIEF.md (3D material plan, hint experiment, 10/30 revision).
## Saves through ResourceSaver so Godot writes every UID. Fails, writing nothing, if a shader or a uniform is missing.
## Run: Godot --headless --path godot --script res://a5/build_a5_materials.gd

const SURFACE := "res://shaders/cobblestone_surface.gdshader"
const HINT := "res://shaders/hint_experiment.gdshader"
const TEX := "res://assets/textures/cobblestone_floor_08/cobblestone_floor_08_%s_1k.png"
const HINT_PNG := "res://a5/hint_experiment/hint_greys_3x1.png"
const ROOM := "res://a3/lantern_gate_room.tscn"

## Material A (Floor) and B (StandIn), values from the brief's material plan.
const MATERIALS := {
	"res://a5/materials/cobblestone_warm_floor.tres": {
		"tint": Color(1.0, 0.92, 0.80, 1.0), "uv_scale": 2.0,
		"roughness_min": 0.55, "roughness_max": 0.95, "normal_strength": 1.0,
	},
	"res://a5/materials/cobblestone_cool_standin.tres": {
		"tint": Color(0.72, 0.85, 1.0, 1.0), "uv_scale": 1.0,
		"roughness_min": 0.20, "roughness_max": 0.55, "normal_strength": 0.5,
	},
}
const HINT_MATERIALS := {
	"res://a5/hint_experiment/hint_with_source_color.tres": true,
	"res://a5/hint_experiment/hint_without_source_color.tres": false,
}

func _initialize() -> void:
	var surface: Shader = _shader(SURFACE, ["color_tex", "normal_tex", "roughness_tex", "tint", "uv_scale", "roughness_min", "roughness_max", "normal_strength"])
	var hint: Shader = _shader(HINT, ["color_sample", "raw_sample", "use_color"])
	if surface == null or hint == null:
		quit(1)
		return
	DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path("res://a5/materials"))
	var saved := {}
	for path in MATERIALS:
		var mat := ShaderMaterial.new()
		mat.shader = surface
		mat.set_shader_parameter("color_tex", load(TEX % "diff"))
		mat.set_shader_parameter("normal_tex", load(TEX % "nor_gl"))
		mat.set_shader_parameter("roughness_tex", load(TEX % "rough"))
		for k in MATERIALS[path]:
			mat.set_shader_parameter(k, MATERIALS[path][k])
		_save(mat, path)
		saved[path] = load(path)
	for path in HINT_MATERIALS:
		var mat := ShaderMaterial.new()
		mat.shader = hint
		var png: Texture2D = load(HINT_PNG)
		mat.set_shader_parameter("color_sample", png)
		mat.set_shader_parameter("raw_sample", png)
		mat.set_shader_parameter("use_color", HINT_MATERIALS[path])
		_save(mat, path)
	_build_material_room(saved)
	_build_hint_scene()
	print("build_a5_materials: done")
	quit()

func _shader(path: String, uniforms: Array) -> Shader:
	if not ResourceLoader.exists(path):
		push_error("missing shader %s" % path)
		return null
	var s: Shader = load(path)
	var names := s.get_shader_uniform_list().map(func(u): return u.name)
	for n in uniforms:
		if not n in names:
			push_error("%s does not declare %s (declares %s)" % [path, n, names])
			return null
	return s

func _save(res: Resource, path: String) -> void:
	var err := ResourceSaver.save(res, path)
	print("saved %s: %s" % [path, error_string(err)])

## An inherited scene: the A3 room unchanged, with only the two material_override properties replaced.
## Packing an instance made with GEN_EDIT_STATE_MAIN_INHERITED from a script saved a full copy of the room, so the
## inherited scene is written as text (paths only, no UIDs) and then loaded and re-saved so Godot normalizes it.
func _build_material_room(_saved: Dictionary) -> void:
	var path := "res://a5/material_room.tscn"
	var f := FileAccess.open(path, FileAccess.WRITE)
	f.store_string("\n".join([
		"[gd_scene format=3]", "",
		"[ext_resource type=\"PackedScene\" path=\"%s\" id=\"1_room\"]" % ROOM,
		"[ext_resource type=\"Material\" path=\"res://a5/materials/cobblestone_warm_floor.tres\" id=\"2_floor\"]",
		"[ext_resource type=\"Material\" path=\"res://a5/materials/cobblestone_cool_standin.tres\" id=\"3_standin\"]", "",
		"[node name=\"LanternGateRoom\" instance=ExtResource(\"1_room\")]", "",
		"[node name=\"Mesh\" parent=\"Floor\"]", "material_override = ExtResource(\"2_floor\")", "",
		"[node name=\"Mesh\" parent=\"StandIn\"]", "material_override = ExtResource(\"3_standin\")", ""]))
	f.close()
	var packed: PackedScene = ResourceLoader.load(path, "", ResourceLoader.CACHE_MODE_IGNORE)
	_save(packed, path)

## Two unshaded quads facing an orthographic camera, Linear tonemap at exposure 1, glow, fog and adjustments off.
func _build_hint_scene() -> void:
	var root := Node3D.new()
	root.name = "HintExperiment"
	var env := Environment.new()
	env.background_mode = Environment.BG_COLOR
	env.background_color = Color(0, 0, 0)
	env.tonemap_mode = Environment.TONE_MAPPER_LINEAR
	env.tonemap_exposure = 1.0
	env.glow_enabled = false
	env.fog_enabled = false
	env.adjustment_enabled = false
	var world := WorldEnvironment.new()
	world.name = "WorldEnvironment"
	world.environment = env
	_add(root, world)
	var cam := Camera3D.new()
	cam.name = "Camera3D"
	cam.projection = Camera3D.PROJECTION_ORTHOGONAL
	cam.size = 4.5
	cam.position = Vector3(0, 0, 5)
	cam.current = true
	_add(root, cam)
	var quads := [["QuadWithSourceColor", -1.75, "res://a5/hint_experiment/hint_with_source_color.tres", "source_color"],
		["QuadWithoutHint", 1.75, "res://a5/hint_experiment/hint_without_source_color.tres", "no hint"]]
	for q in quads:
		var quad := MeshInstance3D.new()
		quad.name = q[0]
		var mesh := QuadMesh.new()
		mesh.size = Vector2(3.0, 1.0)
		quad.mesh = mesh
		quad.position = Vector3(q[1], 0, 0)
		quad.material_override = load(q[2])
		_add(root, quad)
		var label := Label3D.new()
		label.name = q[0] + "Label"
		label.text = q[3]
		label.position = Vector3(q[1], 0.9, 0)
		label.font_size = 48
		_add(root, label)
	var packed := PackedScene.new()
	packed.pack(root)
	_save(packed, "res://a5/hint_experiment/hint_experiment.tscn")
	root.free()

func _add(root: Node, child: Node) -> void:
	root.add_child(child)
	child.owner = root

extends Node3D

# A3-R3: an orbit camera, so the human check can look behind and below the props.
const ORBIT_TARGET := Vector3(0.0, 1.15, 0.0)
const TURN_SPEED := 1.6  # radians per second while Q/E or R/F is held
const ZOOM_SPEED := 6.0  # metres per second while Z/X is held
const PITCH_MIN := deg_to_rad(-50.0)
const PITCH_MAX := deg_to_rad(80.0)
const DISTANCE_MIN := 3.0
const DISTANCE_MAX := 14.0
const DRAG_RADIANS_PER_PIXEL := 0.008
const WHEEL_STEP := 0.5

@onready var stand_in: CharacterBody3D = $StandIn
@onready var camera: Camera3D = $Camera3D
@onready var floor_mesh: MeshInstance3D = $Floor/Mesh

var yaw := 0.0
var pitch := 0.0
var distance := 0.0
var dragging := false

func _ready() -> void:
	_ensure_inputs()
	# Start the orbit from the camera position saved in the scene, so the opening view is unchanged.
	var offset := camera.position - ORBIT_TARGET
	distance = offset.length()
	pitch = asin(offset.y / distance)
	yaw = atan2(offset.x, offset.z)
	_place_camera()

func _process(delta: float) -> void:
	var turn := Input.get_axis("a3_orbit_left", "a3_orbit_right")
	var tilt := Input.get_axis("a3_tilt_down", "a3_tilt_up")
	var zoom := Input.get_axis("a3_zoom_in", "a3_zoom_out")
	if turn != 0.0 or tilt != 0.0 or zoom != 0.0:
		orbit(turn * TURN_SPEED * delta, tilt * TURN_SPEED * delta, zoom * ZOOM_SPEED * delta)

func _physics_process(_delta: float) -> void:
	var axis := Input.get_vector("move_left", "move_right", "move_up", "move_down")
	stand_in.velocity = Vector3(axis.x, 0.0, axis.y) * 2.0
	stand_in.move_and_slide()

func orbit(d_yaw: float, d_pitch: float, d_distance := 0.0) -> void:
	yaw = wrapf(yaw + d_yaw, -PI, PI)
	pitch = clampf(pitch + d_pitch, PITCH_MIN, PITCH_MAX)
	distance = clampf(distance + d_distance, DISTANCE_MIN, DISTANCE_MAX)
	_place_camera()

func _place_camera() -> void:
	camera.position = ORBIT_TARGET + Vector3(sin(yaw) * cos(pitch), sin(pitch), cos(yaw) * cos(pitch)) * distance
	camera.look_at(ORBIT_TARGET)
	# Below the floor's top only its picture is hidden; the floor collider stays.
	floor_mesh.visible = camera.position.y >= 0.0

func _unhandled_input(event: InputEvent) -> void:
	if event is InputEventMouseButton:
		if event.button_index == MOUSE_BUTTON_RIGHT:
			dragging = event.pressed
		elif event.pressed and event.button_index == MOUSE_BUTTON_WHEEL_UP:
			orbit(0.0, 0.0, -WHEEL_STEP)
		elif event.pressed and event.button_index == MOUSE_BUTTON_WHEEL_DOWN:
			orbit(0.0, 0.0, WHEEL_STEP)
	elif event is InputEventMouseMotion and dragging:
		orbit(-event.relative.x * DRAG_RADIANS_PER_PIXEL, event.relative.y * DRAG_RADIANS_PER_PIXEL)
	elif event.is_action_pressed("debug_collision"):
		get_tree().debug_collisions_hint = not get_tree().debug_collisions_hint
	elif event.is_action_pressed("ui_cancel"):
		get_tree().change_scene_to_file("res://game/main.tscn")

func _ensure_inputs() -> void:
	var keys := {
		"move_left": [KEY_A, KEY_LEFT],
		"move_right": [KEY_D, KEY_RIGHT],
		"move_up": [KEY_W, KEY_UP],
		"move_down": [KEY_S, KEY_DOWN],
		"debug_collision": [KEY_F3],
		"a3_orbit_left": [KEY_Q],
		"a3_orbit_right": [KEY_E],
		"a3_tilt_up": [KEY_R],
		"a3_tilt_down": [KEY_F],
		"a3_zoom_in": [KEY_Z],
		"a3_zoom_out": [KEY_X],
	}
	for action in keys:
		if not InputMap.has_action(action):
			InputMap.add_action(action)
		for code in keys[action]:
			var key := InputEventKey.new()
			key.physical_keycode = code
			InputMap.action_add_event(action, key)

extends SceneTree
## Calibration run for normal_map_check.gd on the Poly Haven GL/DX pair of Cobblestone Floor 08.
## Not a suite: it prints the four ratios that set the pass threshold. Decodes the source PNGs, not the imports.
const Check = preload("res://tests/normal_map_check.gd")
const DIR := "res://assets/textures/cobblestone_floor_08/"

func _initialize() -> void:
	for m in ["nor_gl", "nor_dx"]:
		var img := Image.load_from_file(ProjectSettings.globalize_path(DIR + "cobblestone_floor_08_%s_1k.png" % m))
		print("%s %dx%d: curl_ratio directx=false %.4f, directx=true %.4f" % [m, img.get_width(), img.get_height(),
			Check.curl_ratio(img, false), Check.curl_ratio(img, true)])
	quit()

extends SceneTree
## Writes the hint experiment's 3 x 1 PNG: opaque grey texels 64, 128 and 192 (CHANGE-BRIEF.md, hint experiment).
## Run: Godot --headless --path godot --script res://a5/hint_experiment/make_hint_png.gd
const OUT := "res://a5/hint_experiment/hint_greys_3x1.png"
const GREYS := [64, 128, 192]

func _initialize() -> void:
	var img := Image.create(GREYS.size(), 1, false, Image.FORMAT_RGB8)
	for i in GREYS.size():
		img.set_pixel(i, 0, Color8(GREYS[i], GREYS[i], GREYS[i]))
	var err := img.save_png(OUT)
	print("saved %s (%s): %s" % [OUT, error_string(err), GREYS])
	quit(1 if err != OK else 0)

