func run() -> void:
	suite = "test_materials"
	_check_shader(SURFACE, SURFACE_UNIFORMS)
	_check_shader(HINT, HINT_UNIFORMS)
	_check_materials()
	_check_imports()
	_check_material_room()
	_check_hint_scene()
	_check_normal_maps()
