const VARIANT_TYPE := {"sampler2D": TYPE_OBJECT, "vec4": TYPE_COLOR, "float": TYPE_FLOAT, "bool": TYPE_BOOL}

## Every parameter each material sets; a String is the bound texture's path.
const MATERIALS := {
